// D&D 5e equipment/services catalog, built from the 2024 SRD (SRD 5.2,
// Wizards of the Coast, CC-BY-4.0) equipment tables: Weapons, Armor, Tools,
// Adventuring Gear, Mounts and Vehicles, Food/Drink/Lodging, Lifestyle
// Expenses, and Hirelings & Spellcasting Services. Names, categories, and
// prices reflect that source; every description here is written fresh for
// this project rather than reproduced from any rulebook.
//
// Prices are in gp (1 gp = 10 sp = 100 cp).
//
// `pool` groups categories into where they're offered for selection:
//   'wares'    -> general stores, blacksmiths, outfitters, stables, etc.
//   'menu'     -> taverns and inns
//   'services' -> temples, guides, hirelings, and other paid services

let _id = 0
const next = () => `item-${++_id}`

// `extra` is an optional object: { tags, monsterTypeTags, lootTags } —
// see itemPool.js for what each means. Every field defaults to "not set"
// so untagged items (the vast majority) behave exactly as before.
function make(pool, category, name, priceGp, description, extra) {
  return {
    id: next(),
    pool,
    category,
    name,
    priceGp,
    description,
    tags: extra?.tags || [],
    monsterTypeTags: extra?.monsterTypeTags || [],
    lootTags: extra?.lootTags || null,
  }
}

